INSERT INTO captures (id,week,slug,portal,company,url,brand,r2_key,width,height,palette,analysis,analysis_by,status,captured_at) VALUES ('chatgpt-2026-07-20','2026-07-20','chatgpt','ChatGPT','OpenAI','https://chatgpt.com/','#10a37f',NULL,1280,800,'["#ffffff","#f9f9f9","#10a37f","#ececec","#2d333a"]','ChatGPT leads with a near-blank white canvas and a single centered prompt — ''What can I help with?'' — deferring all chrome to a muted left rail. Hierarchy is radically reductive: one composer, a couple of suggestion chips, and the model switcher tucked at top. The green send affordance is the only saturated element, pulling the eye straight to the primary action.','sample','ok','2026-07-20T09:00:00.000Z');
INSERT INTO captures (id,week,slug,portal,company,url,brand,r2_key,width,height,palette,analysis,analysis_by,status,captured_at) VALUES ('claude-2026-07-20','2026-07-20','claude','Claude','Anthropic','https://claude.ai/','#d97757',NULL,1280,800,'["#f4f3ee","#faf9f5","#d97757","#3d3929","#e6e2d6"]','Claude opts for a warm, paper-like cream ground rather than clinical white, giving the surface an editorial, softer feel. A time-aware greeting and a raised composer card create a calm focal point, while intent chips (Write / Learn / Code) frame the tool as task-oriented. The terracotta accent is used sparingly on the logo, primary button, and send control to keep a single consistent brand thread.','sample','ok','2026-07-20T09:00:00.000Z');
INSERT INTO captures (id,week,slug,portal,company,url,brand,r2_key,width,height,palette,analysis,analysis_by,status,captured_at) VALUES ('gemini-2026-07-20','2026-07-20','gemini','Gemini','Google','https://gemini.google.com/','#4285f4',NULL,1280,800,'["#ffffff","#f0f4f9","#4285f4","#9b72cb","#d96570"]','Gemini anchors the page with an oversized gradient greeting that doubles as brand signature, spanning Google''s blue-to-magenta spectrum. The layout is left-aligned and roomier than its peers, pairing the hero with a row of suggestion cards that preview capabilities rather than starting blank. The rounded ''Ask Gemini'' pill and pill-shaped new-chat button echo Material 3''s fully-rounded geometry throughout.','sample','ok','2026-07-20T09:00:00.000Z');
INSERT INTO captures (id,week,slug,portal,company,url,brand,r2_key,width,height,palette,analysis,analysis_by,status,captured_at) VALUES ('perplexity-2026-07-20','2026-07-20','perplexity','Perplexity','Perplexity AI','https://www.perplexity.ai/','#20808d',NULL,1280,800,'["#ffffff","#f7f7f5","#20808d","#e6e6e3","#1a1a1a"]','Perplexity foregrounds answers over chat — the composer sits centre-stage with ''Search / Research / Labs'' mode pills, framing it as an answer engine rather than a chatbot. A teal accent and generous whitespace keep it calm, while source citations are treated as first-class UI, reinforcing its research positioning.','sample','ok','2026-07-20T09:00:00.000Z');
INSERT INTO captures (id,week,slug,portal,company,url,brand,r2_key,width,height,palette,analysis,analysis_by,status,captured_at) VALUES ('copilot-2026-07-20','2026-07-20','copilot','Microsoft Copilot','Microsoft','https://copilot.microsoft.com/','#0a6ed1',NULL,1280,800,'["#eaf3fb","#ffffff","#0a6ed1","#6db4f2","#2b2b2b"]','Microsoft Copilot leans into a friendly, consumer feel — a soft gradient backdrop, a large centred greeting, and a rounded composer with voice and image entry points. It reads warmer and more playful than its enterprise sibling in Microsoft 365, prioritising approachability over density.','sample','ok','2026-07-20T09:00:00.000Z');
INSERT INTO captures (id,week,slug,portal,company,url,brand,r2_key,width,height,palette,analysis,analysis_by,status,captured_at) VALUES ('mistral-2026-07-20','2026-07-20','mistral','Le Chat','Mistral AI','https://chat.mistral.ai/','#fa520f',NULL,1280,800,'["#ffffff","#fbf6f2","#fa520f","#1a1a1a","#efe7e0"]','Le Chat keeps a crisp, European-minimal aesthetic with Mistral''s orange accent used sparingly against near-white. The composer is front and centre with quick tool toggles (web, code, image), and the overall hierarchy is flat and fast, matching the brand''s efficiency-first positioning.','sample','ok','2026-07-20T09:00:00.000Z');
INSERT INTO captures (id,week,slug,portal,company,url,brand,r2_key,width,height,palette,analysis,analysis_by,status,captured_at) VALUES ('grok-2026-07-20','2026-07-20','grok','Grok','xAI','https://grok.com/','#111111',NULL,1280,800,'["#000000","#111111","#ffffff","#2a2a2a","#8a8a8a"]','Grok commits to a stark monochrome, near-black canvas that signals its X / edgy positioning. The layout is reductive — a centred composer with model and mode toggles — and typography does the heavy lifting, with almost no chrome or colour to distract from the input.','sample','ok','2026-07-20T09:00:00.000Z');
INSERT INTO captures (id,week,slug,portal,company,url,brand,r2_key,width,height,palette,analysis,analysis_by,status,captured_at) VALUES ('deepseek-2026-07-20','2026-07-20','deepseek','DeepSeek','DeepSeek','https://chat.deepseek.com/','#4d6bfe',NULL,1280,800,'["#ffffff","#f3f6ff","#4d6bfe","#eaeef7","#1a1a1a"]','DeepSeek mirrors the reductive white-canvas pattern ChatGPT popularised, with a single centred composer. Its signature move is the pair of toggles beneath the input — ''DeepThink (R1)'' for visible reasoning and ''Search'' — surfacing its reasoning model as a first-class, one-tap choice.','sample','ok','2026-07-20T09:00:00.000Z');
INSERT INTO captures (id,week,slug,portal,company,url,brand,r2_key,width,height,palette,analysis,analysis_by,status,captured_at) VALUES ('meta-ai-2026-07-20','2026-07-20','meta-ai','Meta AI','Meta','https://www.meta.ai/','#0866ff',NULL,1280,800,'["#ffffff","#f0f2ff","#0866ff","#9b5de5","#1c2b33"]','Meta AI is image- and generation-forward, with a bold blue-to-purple identity and prominent ''Imagine'' image prompts rather than a blank chat. The layout borrows from Meta''s social surfaces — rounded, media-rich cards — and assumes a casual, consumer audience woven into Instagram and WhatsApp.','sample','ok','2026-07-20T09:00:00.000Z');
INSERT INTO captures (id,week,slug,portal,company,url,brand,r2_key,width,height,palette,analysis,analysis_by,status,captured_at) VALUES ('manus-2026-07-20','2026-07-20','manus','Manus','Manus AI','https://manus.im/','#5a4d41',NULL,1280,800,'["#1e1b18","#2a2521","#c9a26b","#d8cfc4","#8a7d6d"]','Manus presents as an autonomous agent, not a chatbot — the interface is a split view pairing a conversation with a live ''computer'' workspace where tasks execute step by step. The aesthetic is dark and professional, and the primary affordance is delegating a whole task rather than exchanging messages.','sample','ok','2026-07-20T09:00:00.000Z');
INSERT INTO captures (id,week,slug,portal,company,url,brand,r2_key,width,height,palette,analysis,analysis_by,status,captured_at) VALUES ('poe-2026-07-20','2026-07-20','poe','Poe','Quora','https://poe.com/','#7c3aed',NULL,1280,800,'["#ffffff","#f6f3fd","#7c3aed","#ede8fb","#20123a"]','Poe is an aggregator: a left rail lists dozens of bots (GPT, Claude, and community creations) and the home is a directory grid rather than a single assistant. A purple accent and card-based browsing frame it as an app store for models, optimising for discovery and switching.','sample','ok','2026-07-20T09:00:00.000Z');
INSERT INTO captures (id,week,slug,portal,company,url,brand,r2_key,width,height,palette,analysis,analysis_by,status,captured_at) VALUES ('character-ai-2026-07-20','2026-07-20','character-ai','Character.AI','Character.AI','https://character.ai/','#5b7cfa',NULL,1280,800,'["#1a1830","#2d2b55","#5b7cfa","#c7d0ff","#f0f2ff"]','Character.AI is entertainment-first — the home is a grid of avatar cards for user-created characters, with playful imagery and a discovery feed. Chat is secondary to browsing personalities, and the visual language (rounded avatars, vibrant cards) signals roleplay and companionship over productivity.','sample','ok','2026-07-20T09:00:00.000Z');
INSERT INTO captures (id,week,slug,portal,company,url,brand,r2_key,width,height,palette,analysis,analysis_by,status,captured_at) VALUES ('huggingchat-2026-07-20','2026-07-20','huggingchat','HuggingChat','Hugging Face','https://huggingface.co/chat/','#ff9d00',NULL,1280,800,'["#ffffff","#fff8ec","#ff9d00","#ffd21e","#26221a"]','HuggingChat wears its open-source ethos plainly — a lightweight, developer-leaning layout with a prominent open-model picker and Hugging Face''s yellow-orange accent. It is deliberately unpolished-by-design, prioritising transparency (which model, which tools) over consumer gloss.','sample','ok','2026-07-20T09:00:00.000Z');
INSERT INTO captures (id,week,slug,portal,company,url,brand,r2_key,width,height,palette,analysis,analysis_by,status,captured_at) VALUES ('qwen-2026-07-20','2026-07-20','qwen','Qwen Chat','Alibaba','https://chat.qwen.ai/','#615ced',NULL,1280,800,'["#ffffff","#f4f3fe","#615ced","#e7e5fb","#1a1a2e"]','Qwen (Alibaba) is feature-dense, exposing model variants and multimodal tabs (chat, image, video) up front. A violet accent and a busier toolbar reflect a do-everything positioning, packing more capability into the first screen than its Western minimalist peers.','sample','ok','2026-07-20T09:00:00.000Z');
INSERT INTO captures (id,week,slug,portal,company,url,brand,r2_key,width,height,palette,analysis,analysis_by,status,captured_at) VALUES ('kimi-2026-07-20','2026-07-20','kimi','Kimi','Moonshot AI','https://www.kimi.com/','#6c5ce7',NULL,1280,800,'["#ffffff","#f5f4fb","#6c5ce7","#e9e7f7","#1e1b2e"]','Kimi (Moonshot AI) centres long-context and document work — file and URL upload are prominent, and the composer invites large inputs rather than short prompts. A clean, slightly cool palette with a violet accent keeps focus on the reading and analysis workflow it is known for.','sample','ok','2026-07-20T09:00:00.000Z');
INSERT INTO captures (id,week,slug,portal,company,url,brand,r2_key,width,height,palette,analysis,analysis_by,status,captured_at) VALUES ('you-2026-07-20','2026-07-20','you','You.com','You.com','https://you.com/','#14b8a6',NULL,1280,800,'["#ffffff","#effbf9","#14b8a6","#d6f2ee","#0f2e2a"]','You.com is a search-chat hybrid — a mode switcher lets users pivot between web search and AI answers, foregrounding productivity and sourcing. The layout stays utilitarian and information-dense, positioning it closer to a smart search engine than a personality-driven assistant.','sample','ok','2026-07-20T09:00:00.000Z');
INSERT INTO captures (id,week,slug,portal,company,url,brand,r2_key,width,height,palette,analysis,analysis_by,status,captured_at) VALUES ('pi-2026-07-20','2026-07-20','pi','Pi','Inflection AI','https://pi.ai/','#d99a6c',NULL,1280,800,'["#f7f1e8","#fbf7f0","#d99a6c","#e8dcc9","#3a3229"]','Pi (Inflection) is the outlier on tone — a warm cream palette, soft typography, and a voice-forward, one-message-at-a-time cadence designed to feel like a supportive conversation. It deliberately strips away tools and density to emphasise emotional, unhurried dialogue.','sample','ok','2026-07-20T09:00:00.000Z');
